<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Сколько времени у заказчика на подписание документа о приёмке?", "acceptedAnswer": {"@type": "Answer", "text": "Срок устанавливается контрактом, но не может превышать 20 рабочих дней со дня поступления документа о приёмке в ЕИС (ч. 13 ст. 94 закона № 44-ФЗ). За это время заказчик обязан подписать документ или направить мотивированный отказ."}}, {"@type": "Question", "name": "Может ли контракт установить срок приёмки больше 20 рабочих дней?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Контракт может сократить срок, но не удлинить: условие о большем сроке противоречит части 13 статьи 94."}}, {"@type": "Question", "name": "Что делать, если заказчик просто молчит?", "acceptedAnswer": {"@type": "Answer", "text": "Зафиксировать истечение срока, направить письменный запрос о статусе, затем претензию с расчётом пени. Для работ — оформить односторонний акт по п. 4 ст. 753 ГК. Молчание заказчика — просрочка кредитора."}}, {"@type": "Question", "name": "Действителен ли односторонний акт выполненных работ?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Акт с отметкой об отказе заказчика от подписания — действительное доказательство сдачи работ; суд признает его недействительным, только если мотивы отказа заказчика будут признаны обоснованными."}}, {"@type": "Question", "name": "Работает ли односторонний акт при поставке товара?", "acceptedAnswer": {"@type": "Answer", "text": "Статья 753 ГК относится к подряду. При поставке уклонение заказчика от приёмки доказывается уведомлениями о готовности, передаточными документами и перепиской — с опорой на общие нормы ГК об обязательствах и просрочке кредитора."}}, {"@type": "Question", "name": "Заказчик отказался «без причин» — это законно?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Закон предусматривает только мотивированный отказ с указанием причин. Отказ без конкретики оспаривается, а зафиксированная в ЕИС переписка усиливает позицию исполнителя."}}, {"@type": "Question", "name": "Что делать с мотивированным отказом?", "acceptedAnswer": {"@type": "Answer", "text": "Разделить замечания на обоснованные и спорные: первые устранить и сдать результат заново, по вторым потребовать нормативного обоснования и при необходимости привлечь независимую экспертизу."}}, {"@type": "Question", "name": "Можно ли взыскать оплату без подписанного акта?", "acceptedAnswer": {"@type": "Answer", "text": "Да, при доказанном фактическом исполнении: односторонний акт, исполнительная документация, экспертиза, хронология сдачи. Суды взыскивают оплату, когда уклонение заказчика от приёмки подтверждено."}}, {"@type": "Question", "name": "Какая ответственность грозит заказчику?", "acceptedAnswer": {"@type": "Answer", "text": "Пеня 1/300 ключевой ставки за просрочку оплаты (ч. 5 ст. 34), административная ответственность должностных лиц по ч. 8 ст. 7.30.2 КоАП, судебные издержки."}}, {"@type": "Question", "name": "Как затянутая приёмка влияет на казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Без документа о приёмке нет документа-основания — платёж не пройдёт санкционирование в казначействе, не начнёт течь срок оплаты 10 рабочих дней, не откроется окончательный расчёт и выплата прибыли по контракту."}}, {"@type": "Question", "name": "Куда жаловаться на затягивание приёмки?", "acceptedAnswer": {"@type": "Answer", "text": "Претензия заказчику — обязательный первый шаг. Далее — арбитражный суд; по фактам нарушения сроков оплаты материалы может рассмотреть контрольный орган по ч. 8 ст. 7.30.2 КоАП."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Что делать, если заказчик не подписывает акт приёмки", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Проверьте себя", "text": "Убедитесь, что результат соответствует контракту и комплект приложений полон: сертификаты, паспорта, исполнительная документация."}, {"@type": "HowToStep", "position": 2, "name": "Зафиксируйте сдачу", "text": "Отправьте структурированный документ о приёмке в ЕИС — с этой даты считаются 20 рабочих дней на подписание или мотивированный отказ."}, {"@type": "HowToStep", "position": 3, "name": "Направьте запрос о статусе", "text": "По истечении срока — письменный запрос со ссылкой на ч. 13 ст. 94 закона № 44-ФЗ."}, {"@type": "HowToStep", "position": 4, "name": "Направьте претензию", "text": "Требования: подписать документ о приёмке, оплатить контракт, уплатить пеню 1/300 ключевой ставки за каждый день просрочки."}, {"@type": "HowToStep", "position": 5, "name": "Оформите односторонний акт", "text": "Для работ — акт с отметкой об отказе заказчика по п. 4 ст. 753 ГК, с доказательствами сдачи результата."}, {"@type": "HowToStep", "position": 6, "name": "Обратитесь в суд", "text": "Взыскание оплаты, пени и издержек; при уклонении заказчика от приёмки — ссылка на ст. 406 ГК о просрочке кредитора."}, {"@type": "HowToStep", "position": 7, "name": "Исполните решение через казначейство", "text": "Долг с заказчика-бюджетника взыскивается по главе 24.1 Бюджетного кодекса через орган, обслуживающий его лицевой счёт."}]}
